examples.code:
const results = [
  '5' == 5,           // true — строка привелась к числу
  '5' === 5,          // false — типы разные
  null == undefined,  // true — особое правило нестрогого сравнения
  null === undefined, // false
  NaN === NaN,        // false — NaN не равен даже самому себе
];

document.body.append(results.join(' | '));

const user = { name: 'Вера', address: null };

const city = user?.address?.city ?? 'не указан'; // address === null — цепочка оборвалась без ошибки
const phone = user.phone || 'нет телефона';      // свойства нет → undefined → подставился дефолт

document.body.append(city + ' | ' + phone);

const base = ['молоко', 'хлеб'];
const withEggs = [...base, 'яйца'];        // копия плюс новый элемент
const merged = [...base, 'чай', 'мёд'];    // несколько источников сразу

const settings = { theme: 'dark' };
const full = { ...settings, lang: 'ru' };  // копия объекта с дополнением

base.push('изменение не попало в копию');

document.body.append(withEggs.length + ' | ' + merged.length + ' | ' + full.theme);

